export interface ConnectorConfig {
  /** Airtable API key (Bearer token) */
  airtableApiKey: string
  /** Airtable Base ID (e.g., appXXXXXXXXXXXXXX) */
  baseId: string
  /** Airtable Table Name or ID */
  tableName: string
  /** Name of the email field in Airtable used for filterByFormula lookup */
  emailFieldName: string
  /** Mapping from Jotform field keys (e.g., "field_12345678") to Airtable field names */
  fieldMapping: Record<string, string>
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface JotformSubmission {
  email: string
  [key: `field_${string}`]: string | undefined
}

export interface HandleResult {
  recordId: string
  updatedFields: Record<string, string>
  skippedFields: string[]
}

function isNonEmpty(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0
}

function buildFilterByFormula(emailFieldName: string, emailValue: string): string {
  const escaped = emailValue.replace(/"/g, '\\"')
  return `${emailFieldName}="${escaped}"`
}

async function airtableGet(
  url: string,
  apiKey: string,
  fetchImpl: typeof fetch
): Promise<Response> {
  return fetchImpl(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
  })
}

async function airtablePatch(
  url: string,
  apiKey: string,
  body: Record<string, unknown>,
  fetchImpl: typeof fetch
): Promise<Response> {
  return fetchImpl(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields: body }),
  })
}

export async function handle(
  payload: JotformSubmission,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.email || typeof payload.email !== 'string') {
    throw new Error('Missing required field: email')
  }

  const filterFormula = buildFilterByFormula(config.emailFieldName, payload.email)
  const encodedFormula = encodeURIComponent(filterFormula)
  const findUrl = `https://api.airtable.com/v0/${config.baseId}/${config.tableName}?filterByFormula=${encodedFormula}`

  const findRes = await airtableGet(findUrl, config.airtableApiKey, fetchImpl)
  if (!findRes.ok) {
    throw new Error(`Airtable find record failed: ${findRes.status} ${findRes.statusText} at GET ${findUrl}`)
  }

  const findData = (await findRes.json()) as { records?: Array<{ id: string; fields: Record<string, unknown> }> }
  const record = findData.records?.[0]
  if (!record) {
    throw new Error(`No Airtable record found for email: ${payload.email}`)
  }

  const patchFields: Record<string, string> = {}
  const skippedFields: string[] = []

  for (const [jotformKey, airtableFieldName] of Object.entries(config.fieldMapping)) {
    const value = payload[jotformKey]
    if (isNonEmpty(value)) {
      patchFields[airtableFieldName] = value.trim()
    } else {
      skippedFields.push(jotformKey)
    }
  }

  if (Object.keys(patchFields).length === 0) {
    return {
      recordId: record.id,
      updatedFields: {},
      skippedFields,
    }
  }

  const patchUrl = `https://api.airtable.com/v0/${config.baseId}/${config.tableName}/${record.id}`
  const patchRes = await airtablePatch(patchUrl, config.airtableApiKey, patchFields, fetchImpl)
  if (!patchRes.ok) {
    throw new Error(`Airtable update record failed: ${patchRes.status} ${patchRes.statusText} at PATCH ${patchUrl}`)
  }

  return {
    recordId: record.id,
    updatedFields: patchFields,
    skippedFields,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, JotformSubmission } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTestBase',
      tableName: 'Table1',
      emailFieldName: 'email',
      fieldMapping: {
        field_12345678: 'Name',
        field_87654321: 'Company',
      },
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.recordId).toBe('recABC123')
    expect(result.updatedFields).toEqual({ Name: 'John Doe', Company: 'Acme Corp' })
  })
})

describe('handle', () => {
  it('throws when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: {},
      fetch,
    }
    const payload = { field_1: 'value' } as JotformSubmission
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email')
  })

  it('throws when email is empty string', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: {},
      fetch,
    }
    const payload = { email: '', field_1: 'value' } as JotformSubmission
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email')
  })

  it('throws when Airtable find returns no records', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ records: [] }, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: { field_1: 'Name' },
      fetch,
    }
    const payload = { email: 'test@example.com', field_1: 'John' } as JotformSubmission
    await expect(handle(payload, config)).rejects.toThrow('No Airtable record found for email: test@example.com')
    expect(calls[0].url).toContain('filterByFormula=email%3D%22test%40example.com%22')
  })

  it('properly URL-encodes email with special characters', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ records: [{ id: 'rec1', fields: {} }] }, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: {},
      fetch,
    }
    const payload = { email: 'bob+1@gmail.com' } as JotformSubmission
    await handle(payload, config)
    expect(calls[0].url).toContain('filterByFormula=email%3D%22bob%2B1%40gmail.com%22')
  })

  it('only patches non-empty mapped fields and tracks skipped', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec1', fields: { email: 'a@b.com' } }] }, 200)
      }
      return jsonResponse({ id: 'rec1', fields: { email: 'a@b.com', Name: 'John' } }, 200)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: {
        field_1: 'Name',
        field_2: 'Company',
        field_3: 'Phone',
      },
      fetch,
    }
    const payload = {
      email: 'a@b.com',
      field_1: 'John',
      field_2: '',
      field_3: '   ',
    } as JotformSubmission
    const result = await handle(payload, config)
    expect(result.updatedFields).toEqual({ Name: 'John' })
    expect(result.skippedFields).toEqual(['field_2', 'field_3'])
    expect(calls[1].json).toEqual({ fields: { Name: 'John' } })
  })

  it('returns early with no patch when all mapped fields are empty', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec1', fields: {} }] }, 200)
      }
      return jsonResponse({}, 200)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: { field_1: 'Name' },
      fetch,
    }
    const payload = { email: 'a@b.com', field_1: '' } as JotformSubmission
    const result = await handle(payload, config)
    expect(result.updatedFields).toEqual({})
    expect(result.skippedFields).toEqual(['field_1'])
    expect(calls.length).toBe(1)
  })

  it('throws on non-2xx from Airtable find', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config: ConnectorConfig = {
      airtableApiKey: 'bad-key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: {},
      fetch,
    }
    const payload = { email: 'a@b.com' } as JotformSubmission
    await expect(handle(payload, config)).rejects.toThrow('Airtable find record failed: 401 Unauthorized at GET')
    expect(calls.length).toBe(1)
  })

  it('throws on non-2xx from Airtable patch', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec1', fields: {} }] }, 200)
      }
      return jsonResponse({ error: 'Not Found' }, 404)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: { field_1: 'Name' },
      fetch,
    }
    const payload = { email: 'a@b.com', field_1: 'John' } as JotformSubmission
    await expect(handle(payload, config)).rejects.toThrow('Airtable update record failed: 404 Not Found at PATCH')
    expect(calls.length).toBe(2)
  })

  it('uses injected fetch from config', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec1', fields: {} }] }, 200)
      }
      return jsonResponse({ id: 'rec1', fields: {} }, 200)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      emailFieldName: 'email',
      fieldMapping: { field_1: 'Name' },
      fetch,
    }
    const payload = { email: 'a@b.com', field_1: 'John' } as JotformSubmission
    await handle(payload, config)
    expect(calls.length).toBe(2)
  })
})

